using System;
using System.Drawing;
using WoWProbe;
class QuickVendorTests
{
    static int passed,failed;static void Check(bool x){if(!x)throw new Exception("Vendor behavior differs.");}
    static QuickRoutePlan Plan(){var r=new RouteDocument{RouteId="test",Name="test",RouteType="farm",MapId=42,MapMode=1,Zone="TEST",Loop=true};r.Points.Add(new Waypoint{X=.5,Y=.5,Tolerance=.001});r.Points.Add(new Waypoint{X=.52,Y=.5,Tolerance=.001});r.Points.Add(new Waypoint{X=.5,Y=.5,Tolerance=.001});return new QuickRoutePlan{Route=r,Calibration=new NavigationCalibration{MapId=42,MapMode=1,Zone="TEST",Confirmed=true},Vendor=new QuickVendorSettings{Enabled=true,X=.5,Y=.5,RouteComplete=true,Points=new System.Collections.Generic.List<Waypoint>{new Waypoint{X=.5005,Y=.5,Tolerance=.0004},new Waypoint{X=.5,Y=.5,Tolerance=.0004}}}};}
    static OperationObservation O(){return new OperationObservation{Fresh=true,CursorKnown=true,CursorEmpty=true,ConfirmationKnown=true,FreeSlotsKnown=true,InventoryEventsKnown=true,InventoryKnown=true,InventoryRevision=1,MerchantKnown=true,Farm=new FarmObservation{Fresh=true,KnownCore=true,MapId=42,MapMode=1,Zone="TEST",X=.5,Y=.5,Facing=0,ChatOpenKnown=true,CastingKnown=true,Health=100,BagFull=true}};}
    static void Npc(OperationObservation o){var f=o.Farm;f.TargetExists=f.TargetIdentityKnown=f.NameHashKnown=f.AttackabilityKnown=f.TargetDeadKnown=true;f.TargetName="商人";f.TargetNameHash=TargetCatalog.HashName(f.TargetName);f.TargetToken=9;}
    static QuickVendorCommand Step(QuickVendorEngine e,OperationObservation o,long t){o.Sequence++;o.Farm.Sequence=o.Sequence;return e.Step(o,t);}
    static void SecondVisit(QuickVendorEngine e,OperationObservation o,long t){o.MerchantOpen=true;o.MerchantOpened++;Step(e,o,t);Check(Step(e,o,t+2999).Action==QuickVendorAction.None);var c=Step(e,o,t+3000);if(c.Key!=27)c=Step(e,o,t+3600);Check(c.Key==27);o.MerchantOpen=false;o.MerchantClosed++;Step(e,o,t+3700);FinishReturn(e,o,t+3800);}
    static void FinishReturn(QuickVendorEngine e,OperationObservation o,long t){for(int i=0;i<4;i++)Step(e,o,t+i*100);o.Farm.X=.5005;for(int i=4;i<12;i++)if(Step(e,o,t+i*100).Action==QuickVendorAction.Complete)return;throw new Exception("Did not finish recorded return.");}
    static void Test(string name,Action f){try{f();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static int Main()
    {
        Test("emergency repair enters stealth once and does not toggle an already stealthed character",()=>{foreach(bool stealthed in new[]{false,true}){var p=Plan();p.Repair=p.Vendor.Clone();p.Repair.X=.55;p.Repair.Points[1].X=.55;var o=O();o.Farm.GearKnown=o.Farm.GearRed=o.Farm.StealthKnown=true;o.Farm.Durability=0;o.Farm.Stealthed=stealthed;var e=new QuickVendorEngine(p,o,true,false,true);var c=Step(e,o,0);Check((c.Action==QuickVendorAction.Stealth)==!stealthed);if(!stealthed){Check(c.Key==81);e.ConfirmStealthCommand(c);o.Farm.Stealthed=true;Check(Step(e,o,100).Action!=QuickVendorAction.Stealth);}}});
        Test("NPC arrival exits stealth before interaction",()=>{var p=Plan();p.Repair=p.Vendor.Clone();var o=O();Npc(o);o.Farm.GearKnown=o.Farm.GearRed=o.Farm.StealthKnown=o.Farm.Stealthed=true;o.Farm.Durability=0;var e=new QuickVendorEngine(p,o,true,false,true);var c=Step(e,o,0);Check(c.Action==QuickVendorAction.Stealth&&c.Key==81);e.ConfirmStealthCommand(c);Check(Step(e,o,100).Action==QuickVendorAction.None);o.Farm.Stealthed=false;Check(Step(e,o,200).Key==70);});
        Test("saved repair restores exact pending waypoint and ignores elapsed waypoint limit",()=>{var p=Plan();p.Repair=p.Vendor.Clone();p.Repair.X=.55;p.Repair.Points[1].X=.55;var o=O();o.Farm.GearKnown=o.Farm.GearRed=o.Farm.StealthKnown=o.Farm.Stealthed=true;o.Farm.Durability=0;var e=new QuickVendorEngine(p,o,true,false,true);Step(e,o,0);Step(e,o,100);var cp=e.Checkpoint;Check(cp.Next>0);string file=System.IO.Path.GetTempFileName();try{QuickVendorCheckpoint.Save(file,cp);var loaded=QuickVendorCheckpoint.Load(file);var resumed=new QuickVendorEngine(loaded,o);Check(resumed.Checkpoint.Next==cp.Next);Check(resumed.Checkpoint.Path.Points[cp.Next].X==cp.Path.Points[cp.Next].X);Step(resumed,o,200);var c=Step(resumed,o,9000000);Check(c.Action!=QuickVendorAction.Stop);QuickVendorCheckpoint.Save(file,null);Check(!System.IO.File.Exists(file));}finally{if(System.IO.File.Exists(file))System.IO.File.Delete(file);}});
        Test("outbound resumes after long combat without expiring the whole trip",()=>{var p=Plan();p.Vendor.X=.55;p.Vendor.Points[1].X=.55;var o=O();var e=new QuickVendorEngine(p,o);Step(e,o,0);o.Farm.InCombat=true;Check(Step(e,o,400000).Action==QuickVendorAction.None);o.Farm.InCombat=false;e.ResumeAfterCombat(o,700000);Check(Step(e,o,700100).Action!=QuickVendorAction.Stop);});
        Test("return navigation starts after six minutes without the old total-trip cutoff",()=>{var p=Plan();p.Repair=p.Vendor.Clone();p.Vendor.Enabled=false;var o=O();Npc(o);o.Farm.GearKnown=true;o.Farm.Durability=10000;var e=new QuickVendorEngine(p,o,true);Check(Step(e,o,0).Key==70);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;Check(Step(e,o,100).Key==27);o.MerchantOpen=false;o.MerchantClosed++;Step(e,o,200);FinishReturn(e,o,700000);});
        Test("zero durability emergency travels under attack while ordinary trips still defend",()=>{foreach(bool broken in new[]{false,true}){var p=Plan();p.Repair=p.Vendor.Clone();p.Repair.X=.55;p.Repair.Points[1].X=.55;var o=O();o.Farm.GearKnown=true;o.Farm.GearRed=broken;o.Farm.Durability=broken?0:1;var e=new QuickVendorEngine(p,o,true,false,true);Check(e.AvoidCombat==broken);o.Farm.InCombat=true;bool moved=false;for(int t=0;t<2000;t+=100){var c=Step(e,o,t);if(c.Action==QuickVendorAction.Key){Check(broken&&e.Matches(c,o,false));moved=true;break;}Check(c.Action==QuickVendorAction.None);}Check(moved==broken);}var q=Plan();q.Repair=q.Vendor.Clone();var attacked=O();attacked.Farm.InCombat=attacked.Farm.GearKnown=attacked.Farm.GearRed=true;attacked.Farm.Durability=0;Check(new QuickVendorEngine(q,attacked,true,false,true).AvoidCombat);});
        Test("inventory changes restart idle wait and unknown inventory never implies nothing to sell",()=>{var o=O();Npc(o);var e=new QuickVendorEngine(Plan(),o);Step(e,o,0);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;Step(e,o,100);o.InventoryRevision++;Check(Step(e,o,3000).Action==QuickVendorAction.None);Check(Step(e,o,5000).Action==QuickVendorAction.None);o.InventoryKnown=false;Check(Step(e,o,6100).Action==QuickVendorAction.None);o.InventoryKnown=true;Step(e,o,6200);Check(Step(e,o,9300).Key==27);});
        Test("blocked NPC travel backs off turns and verifies heading before trying forward",()=>{var p=Plan();p.Vendor.X=.55;p.Vendor.Points[0].X=.5;p.Vendor.Points[1].X=.55;var o=O();o.Farm.Facing=3*Math.PI/2;var e=new QuickVendorEngine(p,o);bool recovered=false;for(long t=0;t<20000;t+=500){var c=Step(e,o,t);if(c.Key==83){Check(Step(e,o,t+100).Key==39);o.Farm.Facing+=.5;Check(Step(e,o,t+200).Key==QuickMovement.Forward);recovered=true;break;}}Check(recovered);});
        Test("shared merchant waits for both automatic sale and repair before reverse return",()=>{var p=Plan();p.Repair=p.Vendor.Clone();var o=O();Npc(o);o.Farm.GearKnown=true;o.Farm.Durability=100;var e=new QuickVendorEngine(p,o);Check(Step(e,o,0).Key==70);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;Step(e,o,100);o.FreeSlots=5;o.InventoryRevision++;o.Farm.BagFull=false;Check(Step(e,o,700).Action==QuickVendorAction.None);o.Farm.Durability=10000;Step(e,o,800);Check(Step(e,o,3100).Action==QuickVendorAction.None);Check(Step(e,o,3700).Key==27);o.MerchantOpen=false;o.MerchantClosed++;Check(Step(e,o,3800).Key==70);SecondVisit(e,o,3900);});
        Test("coordinate-only selection merchant goods actual capacity and return complete",()=>{var p=Plan();var o=O();var e=new QuickVendorEngine(p,o);Check(Step(e,o,0).Action==QuickVendorAction.Select);Npc(o);var c=Step(e,o,100);Check(c.Action==QuickVendorAction.Key&&c.Key==70&&e.Matches(c,o,false));o.Farm.GossipGoodsVisible=true;o.Farm.GossipGoodsRegion=new Rectangle(20,30,120,30);c=Step(e,o,200);Check(c.Action==QuickVendorAction.Goods&&e.Matches(c,o,false));o.Farm.InCombat=true;Check(!e.Matches(c,o,false));o.Farm.InCombat=false;o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;o.MerchantOpened=1;Check(Step(e,o,300).Action==QuickVendorAction.None);o.FreeSlots=5;o.InventoryRevision=2;o.Farm.BagFull=false;Step(e,o,400);Check(Step(e,o,3300).Action==QuickVendorAction.None);Check(Step(e,o,3900).Key==27);o.MerchantOpen=false;o.MerchantClosed=1;Check(Step(e,o,4000).Key==70);SecondVisit(e,o,4100);});
        Test("idle merchant returns without inventing a successful sale",()=>{var o=O();Npc(o);var e=new QuickVendorEngine(Plan(),o);Step(e,o,0);o.MerchantOpen=true;o.MerchantOpened=1;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;Step(e,o,100);Check(Step(e,o,3200).Key==27&&e.NoSaleObserved);});
        Test("wrong npc players changed goods rectangles and stale input are rejected",()=>{var o=O();Npc(o);var e=new QuickVendorEngine(Plan(),o);var c=Step(e,o,0);o.Farm.TargetIsPlayer=true;Check(!e.Matches(c,o,false));o.Farm.TargetIsPlayer=false;o.Farm.GossipGoodsVisible=true;o.Farm.GossipGoodsRegion=new Rectangle(1,2,100,30);c=Step(e,o,100);o.Farm.GossipGoodsRegion=new Rectangle(2,2,100,30);Check(!e.Matches(c,o,false));o.Fresh=false;Check(!e.Matches(c,o,false));});
        Test("food or loot capacity changes before a merchant do not imply a completed sale",()=>{var p=Plan();p.Vendor.X=.6;p.Vendor.Points[1].X=.6;var o=O();var e=new QuickVendorEngine(p,o);o.FreeSlots=1;o.InventoryRevision=2;o.Farm.BagFull=false;e.ResumeAfterCombat(o,100);Check(Step(e,o,200).Action!=QuickVendorAction.Complete);});
        Test("owned selection chat is allowed while ordinary merchant clicks reject open chat",()=>{var o=O();var e=new QuickVendorEngine(Plan(),o);var c=Step(e,o,0);o.Farm.ChatOpen=true;Check(e.Matches(c,o,true)&&!e.Matches(c,o,false));o.Farm.InCombat=true;Check(!e.Matches(c,o,true));});
        Test("repair is one verified button click followed by actual full durability and return",()=>{var p=Plan();p.Repair=p.Vendor.Clone();p.Vendor.Enabled=false;var o=O();Npc(o);o.Farm.GearKnown=o.Farm.GearRed=true;o.Farm.Durability=0;var e=new QuickVendorEngine(p,o,true);Step(e,o,0);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;o.Farm.RepairButtonVisible=o.Farm.RepairButtonEnabled=o.Farm.RepairCostKnown=o.Farm.MoneyKnown=true;o.Farm.RepairCost=50;o.Farm.Money=100;o.Farm.RepairRegion=new Rectangle(10,20,24,24);var c=Step(e,o,100);Check(c.Action==QuickVendorAction.Repair&&e.Matches(c,o,false));o.Farm.RepairCost=60;Check(!e.Matches(c,o,false));o.Farm.RepairCost=50;Check(Step(e,o,150).Action==QuickVendorAction.None);o.Farm.Durability=10000;o.Farm.GearRed=false;Check(Step(e,o,200).Key==27);o.MerchantOpen=false;o.MerchantClosed=1;Step(e,o,300);FinishReturn(e,o,400);});
        Test("insufficient money never clicks the repair button",()=>{var p=Plan();p.Repair=p.Vendor.Clone();p.Vendor.Enabled=false;var o=O();Npc(o);o.Farm.GearKnown=o.Farm.GearRed=true;var e=new QuickVendorEngine(p,o,true);Step(e,o,0);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;o.Farm.RepairButtonVisible=o.Farm.RepairButtonEnabled=o.Farm.RepairCostKnown=o.Farm.MoneyKnown=true;o.Farm.RepairCost=200;o.Farm.Money=100;Check(Step(e,o,100).Action==QuickVendorAction.Stop);});
        Test("combat resumption closes a still-open repaired merchant before returning",()=>{var p=Plan();p.Repair=p.Vendor.Clone();p.Vendor.Enabled=false;var o=O();Npc(o);o.Farm.GearKnown=true;var e=new QuickVendorEngine(p,o,true);Step(e,o,0);o.MerchantOpen=true;o.MerchantTargetToken=9;o.MerchantNameHash=o.Farm.TargetNameHash;Step(e,o,100);o.Farm.Durability=10000;e.ResumeAfterCombat(o,200);Check(Step(e,o,300).Key==27);o.MerchantOpen=false;o.MerchantClosed=1;Step(e,o,400);FinishReturn(e,o,500);});
        Console.WriteLine("Quick vendor tests: "+passed+" passed, "+failed+" failed. Fake observations only; no item or native input.");return failed==0?0:1;
    }
}
